//! Card images: the SVGs generated by `tools/cardgen`, embedded at build
//! time and rendered by `egui_extras` (D-33).

use eframe::egui;
use skat_app::Card;

include!(concat!(env!("OUT_DIR"), "/card_files.rs"));

/// Selectable card faces (D-14).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Deck {
    /// French, four colours (tournament faces), the default.
    French4,
    /// French, two colours.
    French2,
    /// German suits, Altenburg pattern.
    German,
}

impl Deck {
    /// All decks.
    pub const ALL: [Deck; 3] = [Deck::French4, Deck::French2, Deck::German];

    fn dir(self) -> &'static str {
        match self {
            Deck::French4 => "french4",
            Deck::French2 => "french2",
            Deck::German => "german",
        }
    }

    /// Message id of the deck name.
    pub fn message(self) -> &'static str {
        match self {
            Deck::French4 => "deck-french4",
            Deck::French2 => "deck-french2",
            Deck::German => "deck-german",
        }
    }
}

const SUITS: [&str; 4] = ["kreuz", "pik", "herz", "karo"];
const RANKS: [&str; 8] = [
    "sieben", "acht", "neun", "zehn", "bube", "dame", "koenig", "ass",
];

/// Path of a card face below `assets/cards/`.
pub fn face_path(deck: Deck, card: Card) -> String {
    format!(
        "{}/{}-{}.svg",
        deck.dir(),
        SUITS[usize::from(card.suit().index())],
        RANKS[usize::from(card.rank().index())]
    )
}

/// Path of the card back.
pub const BACK: &str = "back.svg";

/// Image source for a path below `assets/cards/`.
pub fn image(path: &str) -> egui::ImageSource<'static> {
    let bytes = CARD_FILES
        .iter()
        .find(|(p, _)| *p == path)
        .map(|(_, b)| *b)
        .unwrap_or_else(|| panic!("card image {path} is not embedded"));
    egui::ImageSource::Bytes {
        uri: format!("bytes://cards/{path}").into(),
        bytes: bytes.into(),
    }
}
